import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_prime_power_base(N):
    """
    Checks if N is a perfect power of a prime p, N = p^a, with a > 1.
    If so, returns (p, a). If multiple such factorizations exist (e.g., 64 = 2^6 = 4^3),
    it returns the factorization where p is prime and a is maximal.
    Since p must be prime, this implies a unique prime base p.
    """
    if N <= 3:
        return None

    # Iterate through possible exponents 'a' starting from the maximum possible down to 2.
    # Maximum a is floor(log2(N)).
    max_a = int(math.log2(N))

    # We check for a factorization p^a where p is prime.
    # If we find one, since p must be prime, this p is unique for N.
    for a in range(max_a, 1, -1):
        # Calculate the potential base p = N^(1/a)
        p_float = N**(1/a)
        p = round(p_float)

        # Check if p is an integer and p >= 2
        if p >= 2 and abs(p - p_float) < 1e-9:
            # Check if p is prime
            if is_prime(p):
                # Verify N is indeed p^a (handle floating point inaccuracies)
                if pow(p, a) == N:
                    return (p, a)

    return None

solutions = []
search_limit = 20

for m in range(1, search_limit + 1):
    for n in range(1, search_limit + 1):
        X = m**2 + n
        Y = m + n**2

        # Check if X is a perfect prime power p^a, a > 1
        result_X = get_prime_power_base(X)

        if result_X is None:
            continue

        p_X, a = result_X

        # Check if Y is a perfect prime power p^b, b > 1, and p_Y == p_X
        result_Y = get_prime_power_base(Y)

        if result_Y is not None:
            p_Y, b = result_Y

            if p_X == p_Y:
                p = p_X
                # Found a solution (m, n, p)
                solutions.append((m, n, p))

# Output results in a structured format for note writing
print("--- Found Solutions (m, n, p) ---")
for sol in solutions:
    print(f"({sol[0]}, {sol[1]}, {sol[2]})")

